// Jonker-Volgenant / LAPJV style? Let's do auction algorithm with epsilon scaling.
// Returns assignment col_of_row[i] = j

extern "C" {

// Dense auction algorithm for square assignment, costs in row-major double*.
// Maximizes value = -cost. Returns 0 on success.
int auction_solve(const double* cost, int n, int* col_of_row, double* price_out) {
    // We minimize cost. Auction on values v = -cost.
    const double INF = 1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);          // owner of column j
    std::vector<int> assignment(n, -1);     // assignment of row i
    std::vector<int> unassigned;
    unassigned.reserve(n);

    // epsilon scaling
    // Estimate cost scale
    double cmax = 0.0;
    for (int i = 0; i < n*n; ++i) {
        double a = std::fabs(cost[i]);
        if (a > cmax) cmax = a;
    }
    if (cmax == 0.0) cmax = 1.0;
    double eps = cmax / 2.0;
    // target eps for exactness: smaller than min cost gap. Use very small.
    const double eps_target = 1e-12 * std::max(1.0, cmax);
    const double eps_factor = 0.25;

    std::vector<double> best_val(n);
    std::vector<int> best_col(n);

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        unassigned.clear();
        for (int i = 0; i < n; ++i) unassigned.push_back(i);

        int iter_guard = 0;
        const int iter_limit = n * 50 + 1000;
        while (!unassigned.empty()) {
            if (++iter_guard > iter_limit) break;
            int i = unassigned.back();
            unassigned.pop_back();

            // find best and second best column for row i under value = -cost - price
            double v1 = -INF, v2 = -INF;
            int j1 = 0;
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v > v1) {
                    v2 = v1;
                    v1 = v;
                    j1 = j;
                } else if (v > v2) {
                    v2 = v;
                }
            }
            // bid
            double bid = price[j1] + (v1 - v2) + eps;
            // if v2 stayed -INF (n==1), handle
            if (n == 1) bid = price[j1] + eps;
            price[j1] = bid;
            int prev = owner[j1];
            owner[j1] = i;
            assignment[i] = j1;
            if (prev != -1) {
                assignment[prev] = -1;
                unassigned.push_back(prev);
            }
        }
        if (unassigned.empty()) {
            // feasible assignment found at this eps
            if (eps <= eps_target) break;
            eps = std::max(eps * eps_factor, eps_target);
            if (eps <= eps_target) {
                // one more round at target
            }
            // continue scaling; keep prices (warm)
            // but assignment may be incomplete if we broke due to iter limit
        } else {
            // failed to assign within iter limit; reduce eps and retry from scratch prices? 
            // increase prices stability: reduce eps
            eps *= eps_factor;
            if (eps < eps_target * 0.01) {
                // give up
                return 1;
            }
        }
        if (eps <= eps_target && unassigned.empty()) break;
    }

    for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
    if (price_out) {
        for (int j = 0; j < n; ++j) price_out[j] = price[j];
    }
    return 0;
}

}
