#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>

// Bertsekas auction algorithm for the square assignment problem (minimization).
// epsilon-scaling. Not guaranteed exact for all cost matrices, but very fast.

extern "C" {

int auction_solve(const double* cost, int n, int* col_of_row) {
    const double INF = 1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);

    double cmax = 0.0;
    size_t nn = (size_t)n * (size_t)n;
    for (size_t i = 0; i < nn; ++i) {
        double a = std::fabs(cost[i]);
        if (a > cmax) cmax = a;
    }
    if (cmax == 0.0) cmax = 1.0;

    double eps = cmax * 0.5;
    const double eps_target = 1e-11 * std::max(1.0, cmax);

    std::vector<int> unassigned;
    unassigned.reserve(n);

    int phases = 0;
    while (phases < 60) {
        ++phases;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        unassigned.clear();
        for (int i = 0; i < n; ++i) unassigned.push_back(i);

        int guard = 0;
        int guard_limit = n * 80 + 100;
        bool failed = false;
        while (!unassigned.empty()) {
            if (++guard > guard_limit) { failed = true; break; }
            int i = unassigned.back();
            unassigned.pop_back();

            const double* row = cost + (size_t)i * (size_t)n;
            double v1 = -INF, v2 = -INF;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                double v = -row[j] - price[j];
                if (v > v1) {
                    v2 = v1;
                    v1 = v;
                    j1 = j;
                } else if (v > v2) {
                    v2 = v;
                }
            }
            double inc = (v1 - v2) + eps;
            price[j1] += inc;
            int prev = owner[j1];
            owner[j1] = i;
            assignment[i] = j1;
            if (prev != -1) {
                assignment[prev] = -1;
                unassigned.push_back(prev);
            }
        }
        if (!failed && unassigned.empty() && eps <= eps_target) {
            for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
            return 0;
        }
        if (failed) {
            // reduce eps more aggressively and reset prices
            eps *= 0.2;
            std::fill(price.begin(), price.end(), 0.0);
            if (eps < eps_target * 1e-3) return 1;
        } else {
            eps = std::max(eps * 0.25, eps_target);
        }
    }
    return 2;
}

}
