// Jonker-Volgenant shortest augmenting path assignment algorithm.
// Adapted from the classic implementation (public domain / BSD style used widely).
#include <cstdint>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <algorithm>

static constexpr double BIG = 1e18;

extern "C" int lapjv_solve(const double* cost, int n, int* rowsol_out) {
    // 1-indexed internally to match classic code structure more easily? We'll use 0-index.
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> free_rows(n), pred(n), collist(n), matches(n);
    std::vector<double> d(n);

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -2; // temporarily mark as unmatched but reduced? classic sets colsol=-1 and handles via rowsol
            // We'll just leave unmatched. rowsol already assigned.
        }
    }
    // rebuild colsol from rowsol
    std::fill(colsol.begin(), colsol.end(), -1);
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) {
            free_rows[numfree++] = i;
        } else {
            colsol[rowsol[i]] = i;
        }
    }

    // REDUCTION TRANSFER
    for (int loopcnt = 0; loopcnt < 2; ++loopcnt) {
        int k = 0;
        int prevfree = numfree;
        numfree = 0;
        while (k < prevfree) {
            int i = free_rows[k++];
            double umin = cost[(size_t)i * n] - v[0];
            int j1 = 0;
            double usubmin = BIG;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = cost[(size_t)i * n + j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            if (umin < usubmin) {
                v[j1] -= (usubmin - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin) {
                    // put i0 back at current position (k already incremented)
                    free_rows[--k] = i0;
                } else {
                    free_rows[numfree++] = i0;
                }
            }
        }
    }

    // AUGMENTING ROW REDUCTION complete; now shortest augmenting paths
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        for (int j = 0; j < n; ++j) {
            d[j] = cost[(size_t)freerow * n + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0;
        bool unassigned = false;
        int last = 0;
        double minv = 0.0;
        int endofpath = -1;
        while (!unassigned) {
            if (up == low) {
                last = low - 1;
                minv = d[collist[up]];
                up++;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) {
                            up = low;
                            minv = h;
                        }
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        unassigned = true;
                        break;
                    }
                }
            }
            if (!unassigned) {
                int j1 = collist[low++];
                int i = colsol[j1];
                double h = cost[(size_t)i * n + j1] - v[j1] - minv;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double v2 = cost[(size_t)i * n + j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == minv) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassigned = true;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up] = j;
                                up++;
                            }
                        }
                        d[j] = v2;
                    }
                }
            }
        }
        // update column prices
        for (int k = 0; k <= last; ++k) {
            int j1 = collist[k];
            v[j1] += d[j1] - minv;
        }
        // augmentation
        int i = -1;
        while (i != freerow) {
            i = pred[endofpath];
            colsol[endofpath] = i;
            int j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        }
    }

    for (int i = 0; i < n; ++i) rowsol_out[i] = rowsol[i];
    return 0;
}
