/*
 * Jonker-Volgenant algorithm, adapted from the widely used lapjv implementation
 * (https://github.com/src-d/lapjv), which is a C port of the classic code.
 * Dense square minimization.
 */
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <cstdint>
#include <vector>
#include <algorithm>

static constexpr double FP_BIG = 1e18;

#define SWAP(a,b) { auto _t=(a); (a)=(b); (b)=_t; }

extern "C" int lapjv2(const double* cost, int n, int* rowsol_out) {
    std::vector<double> u(n), v(n, 0.0), d(n);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> freev(n), pred(n), collist(n);

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        int imin = 0;
        double minv = cost[j];
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }

    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) freev[numfree++] = i;
        else colsol[rowsol[i]] = i;
    }

    // REDUCTION TRANSFER
    for (int f = 0; f < numfree; ++f) {
        // actually classic does 2 full scans; we'll do the standard loop below
    }
    // redo properly
    {
        int k, prevfree, i, j, j1, j2, i0;
        double umin, usubmin, h;
        for (int loopcnt = 0; loopcnt < 2; ++loopcnt) {
            k = 0; prevfree = numfree; numfree = 0;
            while (k < prevfree) {
                i = freev[k]; k++;
                umin = cost[(size_t)i*n] - v[0];
                j1 = 0; usubmin = FP_BIG; j2 = -1;
                for (j = 1; j < n; ++j) {
                    h = cost[(size_t)i*n + j] - v[j];
                    if (h < usubmin) {
                        if (h >= umin) { usubmin = h; j2 = j; }
                        else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                    }
                }
                i0 = colsol[j1];
                if (umin < usubmin) v[j1] -= (usubmin - umin);
                else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; }
                rowsol[i] = j1;
                colsol[j1] = i;
                if (i0 >= 0) {
                    if (umin < usubmin) freev[--k] = i0;
                    else freev[numfree++] = i0;
                }
            }
        }
    }

    // AUGMENT
    for (int f = 0; f < numfree; ++f) {
        int freerow = freev[f];
        for (int j = 0; j < n; ++j) {
            d[j] = cost[(size_t)freerow * n + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0, last = 0, endofpath = -1;
        double minv = 0;
        bool found = false;
        int scans = 0;
        while (!found) {
            if (up == low) {
                last = low - 1;
                minv = d[collist[up++]];
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) { up = low; minv = h; }
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (int k = low; k < up; ++k) {
                    if (colsol[collist[k]] < 0) { endofpath = collist[k]; found = true; break; }
                }
            }
            if (!found) {
                if (low >= n) break; // safety
                int j1 = collist[low++];
                int i = colsol[j1];
                double h = cost[(size_t)i * n + j1] - v[j1] - minv;
                for (int k = up; k < n; ++k) {
                    int j = collist[k];
                    double v2 = cost[(size_t)i * n + j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == minv) {
                            if (colsol[j] < 0) { endofpath = j; found = true; break; }
                            else { collist[k] = collist[up]; collist[up++] = j; }
                        }
                        d[j] = v2;
                    }
                }
                if (++scans > n*n) break;
            }
        }
        for (int k = 0; k <= last; ++k) {
            int j1 = collist[k];
            v[j1] += d[j1] - minv;
        }
        int i = -1;
        int guard = 0;
        while (i != freerow && guard++ < n+2) {
            i = pred[endofpath];
            colsol[endofpath] = i;
            int j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = rowsol[i];
    return numfree;
}
