// Sparse Jonker-Volgenant style shortest augmenting path for assignment.
// CSR: row_ptr[n+1], col_ind[nnz], cost[nnz] (float64). Missing edges = forbidden (infinite).
// Returns 0 if a perfect matching is found.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <limits>

extern "C" int sparse_lap(int n, const int* row_ptr, const int* col_ind, const double* cost, int* rowsol_out) {
    const double INF = 1e100;
    std::vector<double> v(n, 0.0), d(n);
    std::vector<int> rowsol(n, -1), colsol(n, -1), pred(n), collist(n);
    std::vector<char> in_tree(n);

    // Column reduction on existing edges
    std::vector<double> colmin(n, INF);
    std::vector<int> colmin_row(n, -1);
    for (int i = 0; i < n; ++i) {
        for (int p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
            int j = col_ind[p];
            double c = cost[p];
            if (c < colmin[j]) { colmin[j] = c; colmin_row[j] = i; }
        }
    }
    for (int j = n-1; j >= 0; --j) {
        if (colmin_row[j] < 0) continue;
        v[j] = colmin[j];
        int i = colmin_row[j];
        if (rowsol[i] < 0) {
            rowsol[i] = j;
            colsol[j] = i;
        }
    }

    std::vector<int> free_rows;
    free_rows.reserve(n);
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows.push_back(i);

    // A couple of reduction-transfer scans over free rows
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> next_free;
        next_free.reserve(free_rows.size());
        for (int idx = 0; idx < (int)free_rows.size(); ++idx) {
            int i = free_rows[idx];
            // find best and second best reduced cost
            double umin = INF, usub = INF;
            int j1 = -1, j2 = -1;
            for (int p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
                int j = col_ind[p];
                double h = cost[p] - v[j];
                if (h < umin) { usub = umin; j2 = j1; umin = h; j1 = j; }
                else if (h < usub) { usub = h; j2 = j; }
            }
            if (j1 < 0) { next_free.push_back(i); continue; }
            int i0 = colsol[j1];
            if (umin < usub) {
                v[j1] -= (usub - umin);
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2; i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) {
                    // displaced row stays in current list position-ish: push front by processing now
                    free_rows.push_back(i0); // will be processed later this pass? may duplicate. handle carefully
                    // mark displaced to be reprocessed
                    rowsol[i0] = -1;
                    next_free.push_back(i0);
                } else {
                    rowsol[i0] = -1;
                    next_free.push_back(i0);
                }
            }
        }
        // remove duplicates / rows that got reassigned
        free_rows.clear();
        for (int i : next_free) if (rowsol[i] < 0) free_rows.push_back(i);
        // unique
        std::sort(free_rows.begin(), free_rows.end());
        free_rows.erase(std::unique(free_rows.begin(), free_rows.end()), free_rows.end());
    }

    // Rebuild free rows from actual assignment (safety)
    std::fill(colsol.begin(), colsol.end(), -1);
    free_rows.clear();
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] >= 0) colsol[rowsol[i]] = i;
        else free_rows.push_back(i);
    }
    // resolve conflicts: if two rows claim same col, the colsol has the last; others become free
    {
        std::vector<int> seen(n, -1);
        std::fill(colsol.begin(), colsol.end(), -1);
        free_rows.clear();
        for (int i = 0; i < n; ++i) {
            int j = rowsol[i];
            if (j < 0) { free_rows.push_back(i); continue; }
            if (colsol[j] >= 0) { rowsol[i] = -1; free_rows.push_back(i); }
            else colsol[j] = i;
        }
    }

    // Shortest augmenting path for each free row
    std::vector<int> touched;
    touched.reserve(n);
    for (int freerow : free_rows) {
        std::fill(d.begin(), d.end(), INF);
        std::fill(in_tree.begin(), in_tree.end(), 0);
        touched.clear();
        for (int p = row_ptr[freerow]; p < row_ptr[freerow+1]; ++p) {
            int j = col_ind[p];
            d[j] = cost[p] - v[j];
            pred[j] = freerow;
            touched.push_back(j);
        }
        int endofpath = -1;
        double minv = 0;
        // Dijkstra-like over sparse edges. Use a simple scan (n is 600, free rows small).
        std::vector<char> scanned(n, 0);
        while (true) {
            // pick unscanned column with smallest d
            int jmin = -1;
            double best = INF;
            for (int j : touched) {
                if (!scanned[j] && d[j] < best) { best = d[j]; jmin = j; }
            }
            if (jmin < 0) break; // no augmenting path
            scanned[jmin] = 1;
            minv = best;
            if (colsol[jmin] < 0) { endofpath = jmin; break; }
            int i = colsol[jmin];
            double h = INF;
            // reduced cost offset: cost(i,jmin) - v[jmin] - minv, but we need cost(i, jmin)
            // find it
            for (int p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
                if (col_ind[p] == jmin) { h = cost[p] - v[jmin] - minv; break; }
            }
            for (int p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
                int j = col_ind[p];
                if (scanned[j]) continue;
                double v2 = cost[p] - v[j] - h;
                if (v2 < d[j]) {
                    if (d[j] == INF) touched.push_back(j);
                    d[j] = v2;
                    pred[j] = i;
                }
            }
        }
        if (endofpath < 0) {
            return 1; // infeasible
        }
        // update duals for scanned columns
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) v[j] += d[j] - minv;
        }
        // augment
        int i = -1;
        int guard = 0;
        while (i != freerow && guard++ <= n) {
            i = pred[endofpath];
            colsol[endofpath] = i;
            int j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) return 2;
        rowsol_out[i] = rowsol[i];
    }
    return 0;
}
