// Fast sparse assignment (minimization) via successive shortest augmenting paths
// with potentials, using a binary heap Dijkstra. CSR input.
#include <vector>
#include <cstdint>
#include <queue>
#include <utility>
#include <algorithm>
#include <cmath>

extern "C" int sparse_lap2(int n, const int* row_ptr, const int* col_ind, const double* cost, int* rowsol_out) {
    const double INF = 1e100;
    std::vector<double> pot(n, 0.0);          // column potentials
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<double> dist(n);
    std::vector<int> prev(n);
    std::vector<int> seen_stamp(n, 0);
    int stamp = 0;

    using Node = std::pair<double, int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;

    for (int src = 0; src < n; ++src) {
        ++stamp;
        if (stamp == 0) { // overflow safety, won't happen at n=600
            std::fill(seen_stamp.begin(), seen_stamp.end(), 0);
            stamp = 1;
        }
        while (!pq.empty()) pq.pop();
        for (int p = row_ptr[src]; p < row_ptr[src+1]; ++p) {
            int j = col_ind[p];
            double d = cost[p] - pot[j];
            dist[j] = d;
            prev[j] = src;
            seen_stamp[j] = stamp;
            pq.emplace(d, j);
        }
        int end = -1;
        double enddist = 0;
        int guard = 0;
        while (!pq.empty()) {
            auto [d, j] = pq.top(); pq.pop();
            if (d != dist[j]) continue; // stale
            if (colsol[j] < 0) { end = j; enddist = d; break; }
            int i = colsol[j];
            // find cost(i, j)
            double cij = 0;
            for (int p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
                if (col_ind[p] == j) { cij = cost[p]; break; }
            }
            double base = cij - pot[j] - d; // so reduced costs relative to this
            // actually we want dist[j2] = dist[j] + reduced(i,j2) - reduced(i,j)
            // reduced(i,j) = cij - pot[j], dist[j] should equal that along shortest path from src with potentials
            for (int p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
                int j2 = col_ind[p];
                double nd = d + cost[p] - pot[j2] - (cij - pot[j]);
                if (seen_stamp[j2] != stamp || nd < dist[j2]) {
                    dist[j2] = nd;
                    prev[j2] = i;
                    seen_stamp[j2] = stamp;
                    pq.emplace(nd, j2);
                }
            }
            if (++guard > n * 8) break;
        }
        if (end < 0) return 1;
        // update potentials for visited nodes
        for (int j = 0; j < n; ++j) {
            if (seen_stamp[j] == stamp && dist[j] < enddist) {
                pot[j] += dist[j] - enddist;
            }
        }
        // augment
        int j = end;
        int guard2 = 0;
        while (guard2++ <= n) {
            int i = prev[j];
            int pj = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            if (i == src) break;
            j = pj;
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = rowsol[i];
    return 0;
}
