// Successive shortest augmenting paths for the assignment problem (minimization).
// CSR graph. Column potentials maintained so reduced costs stay nonnegative.
#include <vector>
#include <cstdint>
#include <queue>
#include <utility>
#include <algorithm>

extern "C" int sparse_lap3(int n, const int* row_ptr, const int* col_ind, const double* cost, int* rowsol_out) {
    const double INF = 1e100;
    std::vector<double> pot(n, 0.0);
    std::vector<int> match_row(n, -1);   // column -> row
    std::vector<int> match_col(n, -1);   // row -> column
    std::vector<double> dist(n);
    std::vector<int> parent_col(n);      // predecessor column on path (for the row that owns this column? )
    // We store, for each column, the row from which we reached it.
    std::vector<int> reach_row(n);
    std::vector<int> stamp(n, 0);
    int cur = 0;

    using Node = std::pair<double, int>;

    for (int src = 0; src < n; ++src) {
        ++cur;
        std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
        // init from src
        for (int p = row_ptr[src]; p < row_ptr[src + 1]; ++p) {
            int j = col_ind[p];
            double d = cost[p] - pot[j];
            dist[j] = d;
            reach_row[j] = src;
            stamp[j] = cur;
            pq.emplace(d, j);
        }
        int sink = -1;
        double sinkdist = 0.0;
        while (!pq.empty()) {
            auto [d, j] = pq.top();
            pq.pop();
            if (stamp[j] != cur || d != dist[j]) continue;
            if (match_row[j] < 0) { sink = j; sinkdist = d; break; }
            int i = match_row[j];
            // reduced cost of the matched edge (i, j)
            double cij = 0.0;
            bool found = false;
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                if (col_ind[p] == j) { cij = cost[p]; found = true; break; }
            }
            double base = d - (cij - pot[j]); // = d - reduced(i,j); should be ~0 if consistent
            // Actually standard: dist to j2 via matched row i:
            // nd = d + (cost(i,j2) - pot[j2]) - (cost(i,j) - pot[j])
            for (int p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                int j2 = col_ind[p];
                double nd = d + (cost[p] - pot[j2]) - (cij - pot[j]);
                if (stamp[j2] != cur || nd < dist[j2] - 1e-15) {
                    dist[j2] = nd;
                    reach_row[j2] = i;
                    stamp[j2] = cur;
                    pq.emplace(nd, j2);
                }
            }
        }
        if (sink < 0) return 1;

        // Update potentials: for every visited column, pot[j] += dist[j] - sinkdist
        // Visited = popped before sink, i.e. dist[j] <= sinkdist and stamp==cur.
        // Doing it for all stamped with dist < INF is the classic approach if we set
        // unvisited dist to sinkdist. We only stamped reached nodes.
        for (int j = 0; j < n; ++j) {
            if (stamp[j] == cur && dist[j] < sinkdist) pot[j] += dist[j] - sinkdist;
        }

        // Augment along path
        int j = sink;
        while (true) {
            int i = reach_row[j];
            int prev_j = match_col[i];
            match_col[i] = j;
            match_row[j] = i;
            if (i == src) break;
            j = prev_j;
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = match_col[i];
    return 0;
}
