// Dense successive shortest augmenting path assignment (minimization).
// cost is row-major n*n.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>

extern "C" int dense_lap(const double* cost, int n, int* rowsol_out) {
    const double INF = 1e100;
    std::vector<double> v(n, 0.0), dist(n);
    std::vector<int> match_row(n, -1), match_col(n, -1), pred(n);
    std::vector<char> scanned(n);

    // column reduction init
    for (int j = n - 1; j >= 0; --j) {
        double m = cost[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (match_col[im] < 0) {
            match_col[im] = j;
            match_row[j] = im;
        }
    }

    for (int src = 0; src < n; ++src) {
        if (match_col[src] >= 0) continue;
        std::fill(scanned.begin(), scanned.end(), 0);
        const double* row = cost + (size_t)src * n;
        for (int j = 0; j < n; ++j) {
            dist[j] = row[j] - v[j];
            pred[j] = src;
        }
        int sink = -1;
        double sinkdist = 0;
        while (true) {
            int jmin = -1;
            double best = INF;
            for (int j = 0; j < n; ++j) if (!scanned[j] && dist[j] < best) { best = dist[j]; jmin = j; }
            if (jmin < 0) return 1;
            scanned[jmin] = 1;
            sinkdist = best;
            if (match_row[jmin] < 0) { sink = jmin; break; }
            int i = match_row[jmin];
            double cij = cost[(size_t)i * n + jmin];
            double h = cij - v[jmin] - best; // so nd = cost(i,j2)-v[j2] - h
            const double* ri = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double nd = ri[j] - v[j] - h;
                if (nd < dist[j]) { dist[j] = nd; pred[j] = i; }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - sinkdist;
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev = match_col[i];
            match_col[i] = j;
            match_row[j] = i;
            if (i == src) break;
            j = prev;
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = match_col[i];
    return 0;
}
