    for (int i = 0; i < n; ++i) {
        const double* row = cost_rowmajor + (size_t)i * n;
        for (int j = 0; j < n; ++j) C[(size_t)j * n + i] = row[j];
    }
    std::vector<double> v(n, 0.0), dist(n);
    std::vector<int> match_row(n, -1), match_col(n, -1), pred(n);
    std::vector<char> scanned(n);

    // init potentials by column mins (contiguous)
    for (int j = 0; j < n; ++j) {
        const double* col = C.data() + (size_t)j * n;
        double m = col[0];
        int im = 0;
        for (int i = 1; i < n; ++i) if (col[i] < m) { m = col[i]; im = i; }
        v[j] = m;
        if (match_col[im] < 0) { match_col[im] = j; match_row[j] = im; }
    }

    for (int src = 0; src < n; ++src) {
        if (match_col[src] >= 0) continue;
        std::fill(scanned.begin(), scanned.end(), 0);
        for (int j = 0; j < n; ++j) {
            dist[j] = C[(size_t)j * n + src] - v[j];
            pred[j] = src;
        }
        int sink = -1;
        double sinkdist = 0;
        while (true) {
            int jmin = -1;
            double best = INF;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j] && dist[j] < best) { best = dist[j]; jmin = j; }
            }
            scanned[jmin] = 1;
            sinkdist = best;
            if (match_row[jmin] < 0) { sink = jmin; break; }
            int i = match_row[jmin];
            double h = C[(size_t)jmin * n + i] - v[jmin] - best;
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double nd = C[(size_t)j * n + i] - v[j] - h;
                if (nd < dist[j]) { dist[j] = nd; pred[j] = i; }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - sinkdist;
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev = match_col[i];
            match_col[i] = j;
            match_row[j] = i;
            if (i == src) break;
            j = prev;
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = match_col[i];
    return 0;
}
