// Forward auction for assignment minimization, epsilon scaling.
// Dense row-major cost. Returns column assigned to each row.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>

extern "C" int auction2(const double* cost, int n, int* col_of_row, double eps_final_scale) {
    const double NEG_INF = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);

    double cmax = 0.0;
    size_t nn = (size_t)n * n;
    // sample scale from a subset for speed
    for (size_t i = 0; i < nn; i += 17) {
        double a = std::fabs(cost[i]);
        if (a > cmax) cmax = a;
    }
    if (cmax == 0) cmax = 1;

    double eps = cmax / 4.0;
    double eps_final = eps_final_scale * std::max(1.0, cmax);

    std::vector<int> unassigned;
    unassigned.reserve(n);

    int phase = 0;
    while (phase++ < 80) {
        std::fill(owner.begin(), owner.end(), -1);
        unassigned.clear();
        for (int i = 0; i < n; ++i) unassigned.push_back(i);

        long guard = 0;
        long guard_limit = (long)n * 40;
        bool failed = false;
        while (!unassigned.empty()) {
            if (++guard > guard_limit) { failed = true; break; }
            int i = unassigned.back();
            unassigned.pop_back();
            const double* row = cost + (size_t)i * n;
            double b1 = NEG_INF, b2 = NEG_INF;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > b1) { b2 = b1; b1 = val; j1 = j; }
                else if (val > b2) b2 = val;
            }
            double bid_inc = (b1 - b2) + eps;
            price[j1] += bid_inc;
            int prev = owner[j1];
            owner[j1] = i;
            if (prev >= 0) unassigned.push_back(prev);
        }
        if (!failed) {
            for (int j = 0; j < n; ++j) assignment[owner[j]] = j;
            if (eps <= eps_final) {
                for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
                return 0;
            }
            eps = std::max(eps * 0.2, eps_final);
        } else {
            eps *= 0.2;
            std::fill(price.begin(), price.end(), 0.0);
            if (eps < eps_final * 0.01) return 1;
        }
    }
    return 2;
}
