// Auction on a k-NN candidate set, then verify global optimality via reduced costs.
// If not optimal, returns code 3 and the caller can fall back.
// cost: row-major. cand: n*k int32 candidate columns per row (not necessarily sorted).
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>

extern "C" int auction_k(const double* cost, int n, const int* cand, int k,
                         int* col_of_row, double eps_final_scale) {
    const double NEG_INF = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assignment(n, -1);
    double cmax = 0.0;
    for (int i = 0; i < n; i += 3) {
        for (int t = 0; t < k; t += 3) {
            double a = std::fabs(cost[(size_t)i * n + cand[(size_t)i * k + t]]);
            if (a > cmax) cmax = a;
        }
    }
    if (cmax == 0) cmax = 1;
    double eps = cmax / 4.0;
    double eps_final = eps_final_scale * std::max(1.0, cmax);
    std::vector<int> unassigned; unassigned.reserve(n);

    int phase = 0;
    while (phase++ < 80) {
        std::fill(owner.begin(), owner.end(), -1);
        unassigned.clear();
        for (int i = 0; i < n; ++i) unassigned.push_back(i);
        long guard = 0;
        long guard_limit = (long)n * 60;
        bool failed = false;
        while (!unassigned.empty()) {
            if (++guard > guard_limit) { failed = true; break; }
            int i = unassigned.back(); unassigned.pop_back();
            const double* row = cost + (size_t)i * n;
            const int* cd = cand + (size_t)i * k;
            double b1 = NEG_INF, b2 = NEG_INF; int j1 = cd[0];
            for (int t = 0; t < k; ++t) {
                int j = cd[t];
                double val = -row[j] - price[j];
                if (val > b1) { b2 = b1; b1 = val; j1 = j; }
                else if (val > b2) b2 = val;
            }
            price[j1] += (b1 - b2) + eps;
            int prev = owner[j1];
            owner[j1] = i;
            if (prev >= 0) unassigned.push_back(prev);
        }
        if (!failed && (int)std::count(owner.begin(), owner.end(), -1) == 0) {
            // all columns owned? owner size n and every person assigned iff no -1
            bool complete = true;
            for (int j = 0; j < n; ++j) if (owner[j] < 0) { complete = false; break; }
            if (!complete) { failed = true; }
            else {
                for (int j = 0; j < n; ++j) assignment[owner[j]] = j;
                if (eps <= eps_final) {
                    // Verify global optimality: prices are bids on -cost, so
                    // dual for minimization: beta_j = -price_j (up to shift).
                    // A row is happy globally if its assigned column minimizes cost_ij + price_j? 
                    // We maximized -cost - price, so assigned j minimizes cost + price.
                    // Check no row has a better column outside candidates.
                    for (int i = 0; i < n; ++i) {
                        int ja = assignment[i];
                        double best = cost[(size_t)i * n + ja] + price[ja];
                        const double* row = cost + (size_t)i * n;
                        for (int j = 0; j < n; ++j) {
                            double val = row[j] + price[j];
                            if (val < best - 1e-9) {
                                // not globally optimal
                                for (int t = 0; t < n; ++t) col_of_row[t] = assignment[t];
                                return 3;
                            }
                        }
                    }
