// Gauss-Seidel epsilon-scaling auction for dense assignment minimization.
// Prices persist across epsilon phases (no reset), which is the standard algorithm.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>

extern "C" int auction_gs(const double* cost, int n, int* col_of_row, double eps_final) {
    const double NEG_INF = -1e300;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);       // column -> row
    std::vector<int> assignment(n, -1);  // row -> column

    double cmax = 0.0;
    size_t nn = (size_t)n * n;
    for (size_t i = 0; i < nn; i += 31) {
        double a = cost[i];
        if (a > cmax) cmax = a;
    }
    if (cmax <= 0) cmax = 1.0;

    double eps = cmax * 0.5;
    if (eps_final <= 0) eps_final = 1e-12 * cmax;

    std::vector<int> unassigned;
    unassigned.reserve(n);
    for (int i = 0; i < n; ++i) unassigned.push_back(i);

    int phase = 0;
    while (phase++ < 100) {
        long guard = 0;
        long guard_limit = (long)n * 100;
        bool failed = false;
        while (!unassigned.empty()) {
            if (++guard > guard_limit) { failed = true; break; }
            int i = unassigned.back();
            unassigned.pop_back();
            const double* row = cost + (size_t)i * n;
            double b1 = NEG_INF, b2 = NEG_INF;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > b1) { b2 = b1; b1 = val; j1 = j; }
                else if (val > b2) { b2 = val; }
            }
            // bid so that j1 is eps-better than second
            double new_price = -row[j1] - b2 + eps;  // price'[j1] = -row[j1] - b2 + eps
            // equivalent increment: (b1 - b2) + eps, since b1 = -row[j1] - price[j1]
            // new_price = price[j1] + (b1 - b2) + eps. Use that for numerical stability.
            new_price = price[j1] + (b1 - b2) + eps;
            price[j1] = new_price;
            int prev = owner[j1];
            if (prev == i) {
                // already owned, nothing
            } else {
                owner[j1] = i;
                if (assignment[i] >= 0 && assignment[i] != j1) {
                    // shouldn't normally happen
                }
                assignment[i] = j1;
                if (prev >= 0) {
                    assignment[prev] = -1;
                    unassigned.push_back(prev);
                }
            }
        }
        if (failed) return 1;
        if (eps <= eps_final) {
            for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
            return 0;
        }
        // decrease eps, keep prices and assignment; re-queue everyone to refine
        eps = std::max(eps * 0.2, eps_final);
        unassigned.clear();
        for (int i = 0; i < n; ++i) unassigned.push_back(i);
        // clear ownership so refinement rebuilds consistently? 
        // Standard GS auction keeps prices but re-bids from scratch with current prices.
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
    }
    return 2;
}
