/*
 * Dense LAPJV-style solver.
 * Column reduction + reduction transfer + augmenting row reduction + Dijkstra augmentation.
 * cost row-major.
 */
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>

extern "C" int lapmod(const double* cost, int n, int* rowsol_out) {
    const double BIG = 1e18;
    std::vector<double> u(n, 0.0), v(n, 0.0), d(n);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> free_rows(n), pred(n), collist(n);
    std::vector<char> in_list(n);

    // ---- COLUMN REDUCTION ----
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) rowsol[imin] = j;
    }
    int numfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) free_rows[numfree++] = i;
        else colsol[rowsol[i]] = i;
    }

    // ---- REDUCTION TRANSFER ----
    for (int loop = 0; loop < 2; ++loop) {
        int k = 0, prevfree = numfree;
        numfree = 0;
        while (k < prevfree) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            double umin = row[0] - v[0];
            int j1 = 0;
            double usub = BIG;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j1]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) free_rows[--k] = i0;
                else free_rows[numfree++] = i0;
            }
        }
    }

    // ---- AUGMENTING ROW REDUCTION (one extra greedy pass) ----
    {
        int k = 0, prevfree = numfree;
        numfree = 0;
        while (k < prevfree) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            double umin = BIG, usub = BIG;
            int j1 = -1, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < umin) { usub = umin; j2 = j1; umin = h; j1 = j; }
                else if (h < usub) { usub = h; j2 = j; }
            }
            int i0 = colsol[j1];
            if (i0 < 0 || (umin < usub && j2 >= 0 && colsol[j2] < 0)) {
                // take free column if second is free and first isn't uniquely better
                if (i0 >= 0) { j1 = j2; }
                rowsol[i] = j1;
                colsol[j1] = i;
            } else {
                rowsol[i] = j1;
                colsol[j1] = i;
                if (i0 >= 0) free_rows[numfree++] = i0;
            }
        }
    }

    // ---- SHORTEST AUGMENTING PATHS for remaining free rows ----
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        if (colsol[rowsol[freerow]] == freerow && rowsol[freerow] >= 0) {
            // still assigned? check
        }
        // if this row got assigned and its column points back, skip
        if (rowsol[freerow] >= 0 && colsol[rowsol[freerow]] == freerow) continue;

        const double* frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0, last = 0, endofpath = -1;
        double minv = 0;
        bool found = false;
        while (!found) {
            if (up == low) {
                last = low - 1;
                minv = d[collist[up]];
                ++up;
                for (int kk = up; kk < n; ++kk) {
                    int j = collist[kk];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) { up = low; minv = h; }
                        collist[kk] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (int kk = low; kk < up; ++kk) {
                    if (colsol[collist[kk]] < 0) { endofpath = collist[kk]; found = true; break; }
                }
            }
            if (!found) {
                int j1 = collist[low++];
                int i = colsol[j1];
                const double* ri = cost + (size_t)i * n;
                double h = ri[j1] - v[j1] - minv;
                for (int kk = up; kk < n; ++kk) {
                    int j = collist[kk];
                    double v2 = ri[j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == minv) {
                            if (colsol[j] < 0) { endofpath = j; found = true; break; }
                            collist[kk] = collist[up];
                            collist[up++] = j;
                        }
                        d[j] = v2;
                    }
                }
            }
        }
        for (int kk = 0; kk <= last; ++kk) {
            int j1 = collist[kk];
            v[j1] += d[j1] - minv;
        }
        int i = -1, guard = 0;
        while (i != freerow && guard++ <= n) {
            i = pred[endofpath];
            colsol[endofpath] = i;
            int j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = rowsol[i];
    return 0;
}
