                int j1 = 0;
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > b1) { b2 = b1; b1 = val; j1 = j; }
                    else if (val > b2) b2 = val;
                }
                j1s[t] = j1;
                b1s[t] = b1;
                b2s[t] = b2;
                bid[t] = price[j1] + (b1 - b2) + eps;
            }
            // apply bids sequentially, highest bid wins per column this round
