// Multi-threaded Gauss-Seidel auction.
// Parallel row scans; bid application is serial (n=600, scan dominates).
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <thread>
#include <atomic>

struct BidResult { double b1, b2; int j1; };

static void scan_range(const double* cost, const double* price, const int* jobs, int begin, int end,
                       int n, BidResult* out) {
    const double NEG_INF = -1e300;
    for (int t = begin; t < end; ++t) {
        int i = jobs[t];
        const double* row = cost + (size_t)i * n;
        double b1 = NEG_INF, b2 = NEG_INF;
        int j1 = 0;
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > b1) { b2 = b1; b1 = val; j1 = j; }
            else if (val > b2) b2 = val;
        }
        out[t].b1 = b1; out[t].b2 = b2; out[t].j1 = j1;
    }
}

extern "C" int auction_mt(const double* cost, int n, int* col_of_row, double eps_final, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    if (nthreads > 8) nthreads = 8;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);
    double cmax = 0.0;
    for (size_t i = 0; i < (size_t)n * n; i += 31) if (cost[i] > cmax) cmax = cost[i];
    if (cmax <= 0) cmax = 1;
    double eps = cmax * 0.5;
    if (eps_final <= 0) eps_final = 1e-12 * cmax;

    std::vector<int> unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = i;
    int nfree = n;
    std::vector<BidResult> results(n);
    std::vector<std::thread> pool;

    int phase = 0;
    while (phase++ < 100) {
        long guard = 0;
        while (nfree > 0 && guard++ < (long)n * 50) {
            // parallel scan of unassigned rows
            int threads = nthreads;
            if (nfree < threads * 4) threads = 1;
            if (threads == 1) {
                scan_range(cost, price.data(), unassigned.data(), 0, nfree, n, results.data());
            } else {
                pool.clear();
                int chunk = (nfree + threads - 1) / threads;
                for (int t = 0; t < threads; ++t) {
                    int b = t * chunk;
                    int e = std::min(nfree, b + chunk);
                    if (b >= e) break;
                    pool.emplace_back(scan_range, cost, price.data(), unassigned.data(), b, e, n, results.data());
                }
                for (auto& th : pool) th.join();
            }
            // apply bids serially in order (GS-like within the batch: first processed wins if we do sequential)
            // Do true sequential application using precomputed bids, but recompute is stale if price changes.
            // For correctness of parallel Jacobi, apply highest bid per column.
            std::vector<int> best_t(n, -1);
            std::vector<double> best_bid(n, -1e300);
            for (int t = 0; t < nfree; ++t) {
                int j = results[t].j1;
                double new_price = price[j] + (results[t].b1 - results[t].b2) + eps;
                if (new_price > best_bid[j]) { best_bid[j] = new_price; best_t[j] = t; }
            }
            std::vector<char> requeued(n, 0);
            std::vector<int> next_free;
            next_free.reserve(nfree);
            for (int j = 0; j < n; ++j) {
                int t = best_t[j];
                if (t < 0) continue;
                int i = unassigned[t];
                price[j] = best_bid[j];
                int prev = owner[j];
                owner[j] = i;
                assignment[i] = j;
                if (prev >= 0 && prev != i && !requeued[prev]) {
                    assignment[prev] = -1;
                    next_free.push_back(prev);
                    requeued[prev] = 1;
                }
            }
            for (int t = 0; t < nfree; ++t) {
                int i = unassigned[t];
                int j = results[t].j1;
                if (owner[j] != i && !requeued[i]) {
                    next_free.push_back(i);
                    requeued[i] = 1;
                }
            }
            nfree = (int)next_free.size();
            for (int t = 0; t < nfree; ++t) unassigned[t] = next_free[t];
        }
        if (nfree > 0) return 1;
        if (eps <= eps_final) {
            for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
            return 0;
        }
        eps = std::max(eps * 0.25, eps_final);
        nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
    }
    return 2;
}
