#include <immintrin.h>
#include <cstdint>
#include <algorithm>
#include <cstdio>
#include <cmath>

// Vectorized argmin of row[j] + price[j], returns j1 and the best and second best values of -(row+price).
struct Res { double b1, b2; int j1; };

static inline Res argmin2_avx(const double* row, const double* price, int n) {
    // We want max of -(row[j]+price[j]), and second max.
    __m256d best = _mm256_set1_pd(-1e300);
    __m256d second = _mm256_set1_pd(-1e300);
    __m256d best_idx = _mm256_set1_pd(0);
    __m256d idx = _mm256_set_pd(3, 2, 1, 0);
    __m256d idx_inc = _mm256_set1_pd(4);
    int j = 0;
    for (; j + 4 <= n; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_setzero_pd(), _mm256_add_pd(r, p)); // -(r+p)
        // compare
        __m256d gt_best = _mm256_cmp_pd(val, best, _CMP_GT_OQ);
        __m256d gt_second = _mm256_cmp_pd(val, second, _CMP_GT_OQ);
        // new second = if val>best: best, else if val>second: val, else second
        __m256d new_second = _mm256_blendv_pd(second, val, gt_second);
        new_second = _mm256_blendv_pd(new_second, best, gt_best);
        second = new_second;
        best_idx = _mm256_blendv_pd(best_idx, idx, gt_best);
        best = _mm256_blendv_pd(best, val, gt_best);
        idx = _mm256_add_pd(idx, idx_inc);
    }
    alignas(32) double bv[4], sv[4], bi[4];
    _mm256_store_pd(bv, best);
    _mm256_store_pd(sv, second);
    _mm256_store_pd(bi, best_idx);
    double b1 = -1e300, b2 = -1e300; int j1 = 0;
    for (int t = 0; t < 4; ++t) {
        if (bv[t] > b1) { b2 = b1; b1 = bv[t]; j1 = (int)bi[t]; }
        else if (bv[t] > b2) b2 = bv[t];
        if (sv[t] > b2 && sv[t] < b1) b2 = sv[t];
        else if (sv[t] > b2 && sv[t] != b1) {
            // sv might equal some other best lane
            if (sv[t] > b2) b2 = sv[t];
        }
    }
    // fix second: it must be the second largest among all lane bests and seconds
    double vals[8];
    for (int t = 0; t < 4; ++t) { vals[t] = bv[t]; vals[t+4] = sv[t]; }
    // b1 is max, b2 should be max of the rest that isn't the same lane as j1's best if equal
    b2 = -1e300;
    for (int t = 0; t < 4; ++t) {
        if (t != (j1 & 3) && bv[t] > b2) b2 = bv[t];
        if (sv[t] > b2) b2 = sv[t];
    }
    for (; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > b1) { b2 = b1; b1 = val; j1 = j; }
        else if (val > b2) b2 = val;
    }
    return {b1, b2, j1};
}

extern "C" int auction_vec(const double* cost, int n, int* col_of_row, double eps_final) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);
    double cmax = 0;
    for (int i = 0; i < n; i += 4) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; j += 16) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax <= 0) cmax = 1;
    double eps = cmax * 0.5;
    if (eps_final <= 0) eps_final = 1e-10 * cmax;
    std::vector<int> unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = i;
    int nfree = n;
    int phase = 0;
    while (phase++ < 60) {
        int guard = 0;
        int limit = n * 20;
        while (nfree > 0 && guard++ < limit) {
            int i = unassigned[--nfree];
            Res r = argmin2_avx(cost + (size_t)i * n, price.data(), n);
            double inc = (r.b1 - r.b2) + eps;
            price[r.j1] += inc;
            int prev = owner[r.j1];
            owner[r.j1] = i;
            assignment[i] = r.j1;
            if (prev >= 0) unassigned[nfree++] = prev;
        }
        if (nfree > 0) return 1;
        if (eps <= eps_final) {
            for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
            return 0;
        }
        eps = std::max(eps * 0.25, eps_final);
        nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
    }
    return 2;
}
