#include <immintrin.h>
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>

struct Res { double b1, b2; int j1; };

static inline Res scan_sse(const double* row, const double* price, int n) {
    // Process 2 doubles at a time (SSE) with explicit second-best tracking per lane is messy.
    // Use AVX scalar-friendly unrolled loop that the compiler vectorizes, plus manual 4-wide
    // with a correct second-best: track best value+index, and second as max of rejected values.
    double b1 = -1e300, b2 = -1e300;
    int j1 = 0;
    int j = 0;
    // 4-way unroll, branchless-ish
    for (; j + 4 <= n; j += 4) {
        double v0 = -(row[j] + price[j]);
        double v1 = -(row[j+1] + price[j+1]);
        double v2 = -(row[j+2] + price[j+2]);
        double v3 = -(row[j+3] + price[j+3]);
        // fold
        double vals[4] = {v0, v1, v2, v3};
        for (int t = 0; t < 4; ++t) {
            double val = vals[t];
            if (val > b1) { b2 = b1; b1 = val; j1 = j + t; }
            else if (val > b2) b2 = val;
        }
    }
    for (; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > b1) { b2 = b1; b1 = val; j1 = j; }
        else if (val > b2) b2 = val;
    }
    return {b1, b2, j1};
}

// AVX2 version with horizontal reduction done carefully.
static inline Res scan_avx(const double* row, const double* price, int n) {
    __m256d bestv = _mm256_set1_pd(-1e300);
    __m256d secondv = _mm256_set1_pd(-1e300);
    __m128i besti = _mm_set1_epi32(-1);
    int j = 0;
    for (; j + 4 <= n; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_xor_pd(_mm256_add_pd(r, p), _mm256_set1_pd(-0.0)); // negate
        // For each lane, update best/second.
        __m256d gt = _mm256_cmp_pd(val, bestv, _CMP_GT_OQ);
        // second = max(second, blend(best, second, gt)) then if val>best second takes old best,
        // else if val>second second takes val.
        __m256d oldbest = bestv;
        __m256d take_as_second = _mm256_and_pd(gt, oldbest);          // where val>best, candidate second = old best
        __m256d keep_second = _mm256_andnot_pd(gt, secondv);
        __m256d mid = _mm256_or_pd(take_as_second, keep_second);      // provisional second before considering val as second
        // where val <= best and val > second, second = val
        __m256d le = _mm256_cmp_pd(val, bestv, _CMP_LE_OQ);
        __m256d gt2 = _mm256_cmp_pd(val, secondv, _CMP_GT_OQ);
        __m256d use_val = _mm256_and_pd(le, gt2);
        secondv = _mm256_blendv_pd(mid, val, use_val);
        bestv = _mm256_blendv_pd(bestv, val, gt);
        // indices
        __m128i idx = _mm_set_epi32(j+3, j+2, j+1, j);
        __m128i mask = _mm256_cvtpd_epi32(gt); // not valid; do scalar mask
        (void)mask; (void)idx; (void)besti;
    }
    alignas(32) double bv[4], sv[4];
    _mm256_store_pd(bv, bestv);
    _mm256_store_pd(sv, secondv);
    // The vector loop above doesn't track indices. Fall back: we still need index.
    // So this function is incomplete; use scalar scan_sse which is unrolled.
    return scan_sse(row, price, n);
}

extern "C" int auction_fast(const double* cost, int n, int* col_of_row, double eps_final) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);
    double cmax = 0;
    for (int i = 0; i < n; i += 4) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; j += 16) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax <= 0) cmax = 1;
    double eps = cmax * 0.5;
    if (eps_final <= 0) eps_final = 1e-9 * std::max(1.0, cmax);
    std::vector<int> unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = i;
    int nfree = n;
    int phase = 0;
    while (phase++ < 50) {
        int guard = 0, limit = n * 25;
        while (nfree > 0 && guard++ < limit) {
            int i = unassigned[--nfree];
            Res r = scan_sse(cost + (size_t)i * n, price.data(), n);
            price[r.j1] += (r.b1 - r.b2) + eps;
            int prev = owner[r.j1];
            owner[r.j1] = i;
            assignment[i] = r.j1;
            if (prev >= 0) unassigned[nfree++] = prev;
        }
        if (nfree > 0) return 1;
        if (eps <= eps_final) {
            for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
            return 0;
        }
        eps = std::max(eps * 0.2, eps_final);
        nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
    }
    return 2;
}
