#include <immintrin.h>
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

// Persistent thread pool for parallel auction scans.
// Each worker scans a slice of the current unassigned list.

struct Res { double b1, b2; int j1; };

static inline Res scan_row(const double* row, const double* price, int n) {
    double b1 = -1e300, b2 = -1e300;
    int j1 = 0;
    int j = 0;
    // 8-unroll
    for (; j + 8 <= n; j += 8) {
        double v0 = -(row[j]   + price[j]);
        double v1 = -(row[j+1] + price[j+1]);
        double v2 = -(row[j+2] + price[j+2]);
        double v3 = -(row[j+3] + price[j+3]);
        double v4 = -(row[j+4] + price[j+4]);
        double v5 = -(row[j+5] + price[j+5]);
        double v6 = -(row[j+6] + price[j+6]);
        double v7 = -(row[j+7] + price[j+7]);
#define UPD(val, idx) if (val > b1) { b2 = b1; b1 = val; j1 = idx; } else if (val > b2) b2 = val;
        UPD(v0, j); UPD(v1, j+1); UPD(v2, j+2); UPD(v3, j+3);
        UPD(v4, j+4); UPD(v5, j+5); UPD(v6, j+6); UPD(v7, j+7);
#undef UPD
    }
    for (; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > b1) { b2 = b1; b1 = val; j1 = j; }
        else if (val > b2) b2 = val;
    }
    return {b1, b2, j1};
}

struct Pool {
    int nthreads;
    std::vector<std::thread> threads;
    std::mutex mu;
    std::condition_variable cv_start, cv_done;
    int epoch = 0;          // incremented to launch work
    int done = 0;
    bool stop = false;
    const double* cost = nullptr;
    const double* price = nullptr;
    const int* jobs = nullptr;
    Res* out = nullptr;
    int n = 0, nfree = 0;

    Pool(int nt) : nthreads(nt) {
        for (int t = 0; t < nthreads; ++t) {
            threads.emplace_back([this, t]{ worker(t); });
        }
    }
    ~Pool() {
        {
            std::lock_guard<std::mutex> lk(mu);
            stop = true;
            epoch++;
        }
        cv_start.notify_all();
        for (auto& th : threads) th.join();
    }
    void worker(int tid) {
        int seen = 0;
        while (true) {
            std::unique_lock<std::mutex> lk(mu);
            cv_start.wait(lk, [&]{ return epoch != seen || stop; });
            if (stop) return;
            seen = epoch;
            int nfree_local = nfree;
            int n_local = n;
            const double* cost_l = cost;
            const double* price_l = price;
            const int* jobs_l = jobs;
            Res* out_l = out;
            int nt = nthreads;
            lk.unlock();
            int chunk = (nfree_local + nt - 1) / nt;
            int b = tid * chunk;
            int e = std::min(nfree_local, b + chunk);
            for (int t = b; t < e; ++t) {
                int i = jobs_l[t];
                out_l[t] = scan_row(cost_l + (size_t)i * n_local, price_l, n_local);
            }
            lk.lock();
            done++;
            if (done == nt) cv_done.notify_one();
        }
    }
    void run(const double* cost_, const double* price_, const int* jobs_, Res* out_, int n_, int nfree_) {
        std::lock_guard<std::mutex> lk(mu);
        cost = cost_; price = price_; jobs = jobs_; out = out_;
        n = n_; nfree = nfree_;
        done = 0;
        epoch++;
        cv_start.notify_all();
    }
    void wait() {
        std::unique_lock<std::mutex> lk(mu);
        cv_done.wait(lk, [&]{ return done == nthreads; });
    }
};

static Pool* gpool = nullptr;

extern "C" void auction_init(int nthreads) {
    if (gpool) return;
    if (nthreads < 1) nthreads = 1;
    gpool = new Pool(nthreads);
}

extern "C" int auction_par(const double* cost, int n, int* col_of_row, double eps_final) {
    if (!gpool) auction_init(4);
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);
    double cmax = 0;
    for (int i = 0; i < n; i += 4) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; j += 16) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax <= 0) cmax = 1;
    double eps = cmax * 0.5;
    if (eps_final <= 0) eps_final = 1e-9 * cmax;
    std::vector<int> unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = i;
    int nfree = n;
    std::vector<Res> results(n);
    int phase = 0;
    while (phase++ < 60) {
        int guard = 0, limit = n * 40;
        while (nfree > 0 && guard++ < limit) {
            if (nfree >= 8) {
                gpool->run(cost, price.data(), unassigned.data(), results.data(), n, nfree);
                gpool->wait();
                // Jacobi apply: best bid per column
                std::vector<int> best_t(n, -1);
                std::vector<double> best_bid(n, -1e300);
                for (int t = 0; t < nfree; ++t) {
                    int j = results[t].j1;
                    double np = price[j] + (results[t].b1 - results[t].b2) + eps;
                    if (np > best_bid[j]) { best_bid[j] = np; best_t[j] = t; }
                }
                std::vector<char> requeued(n, 0);
                std::vector<int> next;
                next.reserve(nfree);
                for (int j = 0; j < n; ++j) {
                    int t = best_t[j];
                    if (t < 0) continue;
                    int i = unassigned[t];
                    price[j] = best_bid[j];
                    int prev = owner[j];
                    owner[j] = i;
                    assignment[i] = j;
                    if (prev >= 0 && prev != i && !requeued[prev]) {
                        assignment[prev] = -1;
                        next.push_back(prev);
                        requeued[prev] = 1;
                    }
                }
                for (int t = 0; t < nfree; ++t) {
                    int i = unassigned[t];
                    if (owner[results[t].j1] != i && !requeued[i]) {
                        next.push_back(i);
                        requeued[i] = 1;
                    }
                }
                nfree = (int)next.size();
                for (int t = 0; t < nfree; ++t) unassigned[t] = next[t];
            } else {
                // serial tail
                int i = unassigned[--nfree];
                Res r = scan_row(cost + (size_t)i * n, price.data(), n);
                price[r.j1] += (r.b1 - r.b2) + eps;
                int prev = owner[r.j1];
                owner[r.j1] = i;
                assignment[i] = r.j1;
                if (prev >= 0) unassigned[nfree++] = prev;
            }
        }
        if (nfree > 0) return 1;
        if (eps <= eps_final) {
            for (int i = 0; i < n; ++i) col_of_row[i] = assignment[i];
            return 0;
        }
        eps = std::max(eps * 0.25, eps_final);
        nfree = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
    }
    return 2;
}
