#include <immintrin.h>
#include <cstdint>
#include <cstdio>
#include <cmath>
#include <vector>
#include <chrono>

struct Res { double b1, b2; int j1; };

static Res scan_scalar(const double* row, const double* price, int n) {
    double b1 = -1e300, b2 = -1e300; int j1 = 0;
    for (int j = 0; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > b1) { b2 = b1; b1 = val; j1 = j; }
        else if (val > b2) b2 = val;
    }
    return {b1, b2, j1};
}

static Res scan_avx(const double* row, const double* price, int n) {
    __m256d bestv = _mm256_set1_pd(-1e300);
    __m256d secondv = _mm256_set1_pd(-1e300);
    __m128i besti = _mm_set1_epi32(-1);
    int j = 0;
    for (; j + 4 <= n; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_setzero_pd(), _mm256_add_pd(r, p));
        __m256d gt = _mm256_cmp_pd(val, bestv, _CMP_GT_OQ);
        __m256d gt2 = _mm256_cmp_pd(val, secondv, _CMP_GT_OQ);
        __m256d ns = _mm256_blendv_pd(secondv, val, gt2);
        ns = _mm256_blendv_pd(ns, bestv, gt);
        secondv = ns;
        bestv = _mm256_blendv_pd(bestv, val, gt);
        __m128i idx = _mm_set_epi32(j + 3, j + 2, j + 1, j);
        int mask = _mm256_movemask_pd(gt);
        __m128i m = _mm_set_epi32((mask & 8) ? -1 : 0, (mask & 4) ? -1 : 0,
                                  (mask & 2) ? -1 : 0, (mask & 1) ? -1 : 0);
        besti = _mm_blendv_epi8(besti, idx, m);
    }
    alignas(32) double bv[4], sv[4];
    alignas(16) int bi[4];
    _mm256_store_pd(bv, bestv);
    _mm256_store_pd(sv, secondv);
    _mm_store_si128(reinterpret_cast<__m128i*>(bi), besti);
    double b1 = -1e300; int j1 = 0, win = 0;
    for (int t = 0; t < 4; ++t) if (bv[t] > b1) { b1 = bv[t]; j1 = bi[t]; win = t; }
    double b2 = -1e300;
    for (int t = 0; t < 4; ++t) {
        if (t != win && bv[t] > b2) b2 = bv[t];
        if (sv[t] > b2) b2 = sv[t];
    }
    for (; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > b1) { b2 = b1; b1 = val; j1 = j; }
        else if (val > b2) b2 = val;
    }
    return {b1, b2, j1};
}

int main() {
    int n = 600;
    std::vector<double> row(n), price(n);
    for (int i = 0; i < n; ++i) { row[i] = std::sin(i * 0.017); price[i] = std::cos(i * 0.013); }
    // correctness over several price states
    int mismatches = 0;
    for (int trial = 0; trial < 100; ++trial) {
        for (int i = 0; i < n; ++i) price[i] = std::sin((i + trial) * 0.01) * (trial + 1);
        auto a = scan_scalar(row.data(), price.data(), n);
        auto b = scan_avx(row.data(), price.data(), n);
        if (a.j1 != b.j1 || std::fabs(a.b1 - b.b1) > 1e-9 || std::fabs(a.b2 - b.b2) > 1e-9) {
            if (mismatches < 5) std::printf("mismatch trial %d scalar j1=%d b1=%.6f b2=%.6f avx j1=%d b1=%.6f b2=%.6f\n",
                trial, a.j1, a.b1, a.b2, b.j1, b.b1, b.b2);
            mismatches++;
        }
    }
    std::printf("mismatches %d/100\n", mismatches);
    // timing
    volatile double sink = 0;
    auto t0 = std::chrono::steady_clock::now();
    for (int rep = 0; rep < 20000; ++rep) {
        auto r = scan_scalar(row.data(), price.data(), n);
        sink += r.b1;
    }
    auto t1 = std::chrono::steady_clock::now();
    for (int rep = 0; rep < 20000; ++rep) {
        auto r = scan_avx(row.data(), price.data(), n);
        sink += r.b1;
    }
    auto t2 = std::chrono::steady_clock::now();
    double ms1 = std::chrono::duration<double, std::milli>(t1 - t0).count();
    double ms2 = std::chrono::duration<double, std::milli>(t2 - t1).count();
    std::printf("scalar %.2f us/scan  avx %.2f us/scan  speedup %.2f  sink %f\n",
                ms1 / 20.0, ms2 / 20.0, ms1 / ms2, sink);
}
